CREATE TABLE solicitacao_titular(id uuid PRIMARY KEY,clinica_id uuid NOT NULL,paciente_id uuid NOT NULL,solicitante_id uuid NOT NULL,tipo varchar(255) NOT NULL CHECK(tipo IN ('ACESSO','CORRECAO','EXCLUSAO','INFORMACAO')),status varchar(255) NOT NULL CHECK(status IN ('ABERTA','CONCLUIDA','INDEFERIDA')),criada_em timestamptz NOT NULL,resposta varchar(2000),respondida_em timestamptz,versao bigint NOT NULL DEFAULT 0,FOREIGN KEY(paciente_id,clinica_id) REFERENCES paciente(id,clinica_id),FOREIGN KEY(solicitante_id,clinica_id) REFERENCES usuario(id,clinica_id));
CREATE INDEX solicitacao_paciente ON solicitacao_titular(clinica_id,paciente_id,criada_em DESC);
